-- PROPOSTA (loja-nichos-15-11, N2): Pets completa - Gato, Passaro, Pequenos animais e Peixe (ordem da caixa 90).
-- Quem aplica: Claude.ai, DEPOIS da N1 (precisa das subcategorias e de cj_listas). 34 produtos da CJ.
-- Escolha: para cada tipo da lista de campeoes da caixa 90, os primeiros resultados da pesquisa da CJ e, entre eles, o
-- de mais "Lists" (lojas que o vendem); fora comida/petiscos/feno/catnip, eletricos, marcas e artigos que nao sao
-- para animais (filtrados a mao, motivo em textos_pt.js no e2e). Fotos = as da ficha da CJ (102 fotos, todas 200 image/*).
-- ARMAZEM: nenhum destes tem stock em armazem da UE na CJ (inventory de cada um: so China) -> prazo 7 a 17 dias uteis.
-- PRECO (regra aprovada, caixa 90): custo = (preco CJ + envio para PT) x 0.90481 + 3,00 EUR de direitos (China);
-- preco = 2 x custo. ENVIO ESTIMADO: o pedido de calculo de envio da CJ passou a responder 400 e o classificador
-- recusou ler os cabecalhos da pagina (docs/TRANCAS.md 15/11 ~20:40), por isso usei a tabela CJPacket Ordinary I
-- medida hoje nos 11 de pets (4,27 USD + 0,01335 USD/g; bateu certo em 8 de 9) + 0,70 USD de folga (o maior desvio).
-- Antes de abrir ao publico: confirmar o envio real de cada um na primeira encomenda (se vier mais caro, subir o preco).
insert into public.loja_online_produtos
  (shopify_product_id, shopify_variant_id, nicho_id, subcategoria_id, titulo, descricao, imagens,
   custo_fornecedor_cents, preco_bora_cents, prazo_min_dias, prazo_max_dias, destaque, cj_listas, ativo)
select v.spid, v.sku, n.id, s.id, v.titulo, v.descricao, v.imagens, v.custo, v.preco, v.pmin, v.pmax, v.destaque, v.listas, true
